contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function f(uint256 amount, address payable recipient) public {
        require(address(this).balance >= amount);
        // fund the target contract via its payable fallback
        address(c).call{value: amount}("");
        require(address(c).balance >= amount);

        // InvMutTest is not the owner of c, so P reverts here (funds stay put),
        // while M transfers the balance away before the require reverts.
        bool reverted;
        try c.withdrawAll(recipient) { reverted = false; }
        catch { reverted = true; }

        assert(reverted);
    }

    receive() external payable {}
    fallback() external payable {}
}

