contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function test(address _recipient) public {
        // The test contract acts as the owner driving the contract.
        require(c.owner() == address(this), "driver must be owner");

        // Fund the contract through its payable fallback.
        require(address(this).balance >= 1 ether);
        (bool ok, ) = address(c).call{value: 1 ether}("");
        require(ok);
        require(address(c).balance == 1 ether);

        // Owner withdraws everything to the recipient.
        c.withdrawAll(_recipient);

        // General rule: an owner-authorized withdrawAll drains the full balance.
        assert(address(c).balance == 0);
    }
}

